import test from 'node:test';import assert from 'node:assert/strict';
import {Game} from '../src/engine.js';import {buildProgress,upgradeOutcome} from '../src/build-plan.js';
const prepare=()=>{const g=new Game({seed:42,starterGadget:'brush'});g.start();g.state='upgrade';g.rollOffers();return g;};
test('marking a build is only a reminder; offers and RNG remain identical',()=>{const g=prepare(),h=prepare(),before=[...g.offers];assert.ok(g.markBuild('washstorm'));assert.deepEqual(g.offers,before);g.rollOffers();h.rollOffers();assert.deepEqual(g.offers,h.offers);assert.equal(buildProgress(g,'washstorm').missing,3);assert.ok(g.markBuild('washstorm'));assert.equal(g.buildGoal,null);});
test('rerolls exclude previous cards, spend a run budget, and cannot grant upgrades',()=>{const g=prepare();for(let i=0;i<3;i++){const before=[...g.offers];assert.ok(g.rerollOffers());assert.equal(g.offers.length,3);assert.equal(new Set(g.offers).size,3);assert.ok(g.offers.every(id=>!before.includes(id)));}assert.equal(g.rerolls,0);assert.equal(g.rerollOffers(),false);assert.equal(g.loadout.length,1);assert.equal(g.mods.brush,1);g.state='playing';assert.equal(g.rerollOffers(),false);g.reset();assert.equal(g.rerolls,3);assert.equal(g.buildGoal,null);});
test('card outcome announces formation and history counts only active combat time',()=>{const g=prepare();g.mods.brush=1;g.mods.electric=2;g.offers=['brush'];assert.match(upgradeOutcome(g,'brush'),/选后成型/);g.chooseUpgrade('brush');assert.equal(g.evolutionHistory.length,1);assert.equal(g.evolutionHistory[0].room,2);g.update(1/60);const t=g.evolutionHistory[0].activeSeconds;g.togglePause();g.update(.1);assert.equal(g.evolutionHistory[0].activeSeconds,t);g.evolutionUse('washstorm');assert.equal(g.summary().evolutionHistory[0].uses,1);g.reset();assert.equal(g.evolutionHistory.length,0);});
test('aimed washing discharges from connected impact foam, with one cooldown',()=>{const g=new Game();g.start();g.enemies=[];g.mods.brush=2;g.mods.electric=2;g.player.x=80;g.player.y=80;g.addFoam(500,300);g.addFoam(600,300);const e=g.spawnEnemy('boss',640,300),hp=e.hp+e.armor;const s={x:500,y:300};g.gadgets.triggerWash(s);assert.ok(e.hp+e.armor<hp);assert.equal(g.stats.manualDischarges,1);g.gadgets.triggerWash(s);assert.equal(g.stats.manualDischarges,1);});
test('transport direction follows the shot and expires rather than overriding aim forever',()=>{const g=new Game();g.start();Object.assign(g.mods,{bubble:2,duck:2,electric:1});g.player.angle=Math.PI/2;const d=g.gadgets.duck;g.gadgets.makeBubble(d.x,d.y,0);g.player.ammo=40;g.fire();const b=g.gadgets.bubbles[0];assert.ok(b.command>0);assert.ok(Math.abs(b.vx)<.001&&b.vy>200);assert.equal(g.stats.deliveries,1);g.gadgets.update(.1);assert.ok(b.command<2.5);});
test('evolved pinball returns charge once and next shot consumes the catch bonus',()=>{const g=new Game();g.start();g.enemies=[];g.spawnEnemy('boss',100,100);g.dirt.fill(1);Object.assign(g.mods,{brush:2,mop:2});g.player.ammo=80;g.fire();const s=g.shots[0];assert.ok(s.evolvedReturn);s.life=1;s.x=g.player.x;s.y=g.player.y;g.update(1/60);assert.ok(g.catchBoost>0);const returns=g.stats.returns;g.update(1/60);assert.equal(g.stats.returns,returns);g.player.ammo=80;g.shotCooldown=0;g.fire();assert.equal(g.catchBoost,0);assert.ok(g.shots.at(-1).damage>(24+80*.6));});
test('late durability is authored by room, not player build, and victory is never gated',()=>{for(const preset of ['normal','wash']){const g=new Game();g.selectPreset(preset);g.room=12;g.setupRoom();g.start();assert.equal(g.enemies.find(e=>e.type==='boss').hp,900);g.dirt.fill(0);g.stage.finish();g.update(1/60);assert.equal(g.clearReason,'clean');}});
